node -e '
const fs = require("fs");
const path = require("path");
const base = path.dirname(require.resolve("@re-cinq/eslint-plugin-re-lint/package.json"));
console.log(fs.readdirSync(path.join(base, "rules")).filter(f => f.includes("test") || f.includes("spec") || f.includes("expect") || f.includes("colocated")));
for (const r of ["require-colocated-tests.js", "require-spec-link.js", "max-expects.js", "test-imports-its-subject.js"]) {
  const p = path.join(base, "rules", r);
  if (fs.existsSync(p)) {
    console.log("=== " + r + " ===");
    console.log(fs.readFileSync(p, "utf8").slice(0, 2500));
  }
}
'

node -e '
const fs = require("fs");
const path = require("path");
const base = "./node_modules/@re-cinq/eslint-plugin-re-lint";
const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
const files = walk(base).filter(f => f.endsWith(".js"));
console.log(files);
for (const name of ["require-colocated-tests.js", "require-spec-link.js", "max-expects.js", "test-imports-its-subject.js", "no-nondeterministic-tests.js"]) {
  const match = files.find(f => f.endsWith("/" + name));
  if (match) {
    console.log("=== " + name + " ===");
    console.log(fs.readFileSync(match, "utf8").slice(0, 3000));
  }
}
'

